import math

def check_n(n):
    """Checks if k^2 = 1 (mod n) for all k coprime to n."""
    if n < 2:
        return False, "n must be >= 2"

    for k in range(1, n):
        if math.gcd(k, n) == 1:
            # Check if k^2 = 1 (mod n)
            if (k * k - 1) % n != 0:
                return False, f"Failed for k={k}. k^2 - 1 = {k*k - 1}, which is not divisible by {n}."
    return True, "Verified"

solutions = []
print("--- Checking n=2 to n=12 ---")
for n in range(2, 13):
    is_solution, message = check_n(n)
    print(f"n={n}: {is_solution} - {message}")
    if is_solution:
        solutions.append(n)

print("\n--- Summary ---")
print("Verified solutions (n <= 12):", solutions)

def check_condition(n):
    if n < 2:
        return False

    # Find all positive integers k such that 1 <= k < n and gcd(k, n) = 1
    import math
    units = [k for k in range(1, n) if math.gcd(k, n) == 1]

    # Check if k^2 = 1 (mod n) for all these units
    for k in units:
        if (k * k - 1) % n != 0:
            print(f"FAIL: n={n}. Found k={k}. k^2 - 1 = {k*k - 1}, which is not divisible by {n}.")
            return False
    return True

# List of all candidates derived from the notes: n = 2^a 3^b where a in {0, 1, 2, 3}, b in {0, 1}, and n >= 2.
# a=0: 3^b -> {3} (b=1). (n=1 excluded)
# a=1: 2*3^b -> {2, 6}
# a=2: 4*3^b -> {4, 12}
# a=3: 8*3^b -> {8, 24}

candidates = [2, 3, 4, 6, 8, 12, 24]

results = {}
for n in candidates:
    results[n] = check_condition(n)

print("Results for all candidates:")
print(results)

